import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // -------------------------------------------------
  // Textured plane (hero subhead background)
  // -------------------------------------------------
  // Preserve aspect ratio of the provided image (512 × 320 → 1.6 : 1)
  const planeGeometry = new PlaneGeometry(1.6, 1);
  const planeMaterial = new MeshBasicNodeMaterial();
  planeMaterial.transparent = false;
  planeMaterial.color = new Color('#ffffff');

  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  root.add(planeMesh);

  // Load texture asynchronously (function stays synchronous)
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/cta-hero-isolated.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    planeMaterial.map = tex;
    planeMaterial.needsUpdate = true;
  });

  // -------------------------------------------------
  // Text content (headline)
  // -------------------------------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const paperColor =
    (config.visual?.colors?.paper ||
      config.colors?.paper ||
      '#e8ecf2');

  for (const item of items) {
    // Expecting plain string in item.text
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: 42,
      color: paperColor,
      align: 'center',
    });
    root.add(txt);
  }

  // -------------------------------------------------
  // Apply cinematic primitives (if any)
  // -------------------------------------------------
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const handle = ctx.primitives[prim.name](root, prim.params);
    primitiveHandles.push(handle);
  }

  // -------------------------------------------------
  // User data & cleanup
  // -------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeometry.dispose();
    planeMaterial.dispose();

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created elsewhere
    if (gsap && typeof gsap.globalTimeline !== 'undefined') {
      gsap.globalTimeline.clear();
    }
  };

  return root;
}
